     3	/** What one damaged item lost in an incident, as the claim report states it. */
     4	export interface Damage {
     5	  itemType: string;
     6	  amount: number;
     7	}
     8	
     9	const DEDUCTIBLE_PER_DAMAGE = 100;
    10	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
    11	const HIGH_ENCHANTMENT_REIMBURSED_SHARE = 0.5;
    12	
    13	/**
    14	 * The claim clause's own enchantment test. The quote side has a high-enchantment
    15	 * rule too, at a different threshold and for a different effect; the two are
    16	 * separate entries in the MHPCO clause book and move independently.
    17	 */
    18	function qualifiesForHighEnchantmentClause(item: Item): boolean {
    19	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
    20	}
    21	
    22	/** The share of a damage the office carries before the deductible is charged. */
    23	function reimbursedShareOf(item: Item): number {
    24	  return qualifiesForHighEnchantmentClause(item) ? HIGH_ENCHANTMENT_REIMBURSED_SHARE : 1;
    25	}
    26	
    27	/**
    28	 * What the office owes for one damaged item: the share its clauses carry, less the
    29	 * deductible charged per damage event -- an incident that harms two items is
    30	 * reduced twice, so the payout is assembled per damaged item rather than per
    31	 * incident.
    32	 */
    33	function reimbursementFor(damage: Damage, damagedItem: Item): number {
    34	  return damage.amount * reimbursedShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
    35	}
    36	
    37	/**
    38	 * The reported item type, resolved against what the policy actually covers. A claim
    39	 * naming an item the policy does not carry is not yet rejected here -- that rule is
    40	 * still driven by an inactive test, so today every reported type is assumed covered.
    41	 */
    42	function insuredItemFor(items: Item[], damage: Damage): Item {
    43	  return items.find((item) => item.type === damage.itemType)!;
    44	}
    45	
    46	export function payoutFor(items: Item[], damages: Damage[]): number {
    47	  return damages.reduce(
    48	    (payout, damage) => payout + reimbursementFor(damage, insuredItemFor(items, damage)),
    49	    0,
    50	  );
    51	}

