  return qualifiesForHighEnchantmentClause(item)
    ? HIGH_ENCHANTMENT_REIMBURSED_SHARE
    : FULL_REIMBURSEMENT;
}
'''
assert old_share in s
s = s.replace(old_share, new_share)
open(p, "w").write(s)
print("patched")
