    14	/**
    15	 * The claim clause's own enchantment test. The quote side has a high-enchantment
    16	 * rule too, at a different threshold and for a different effect; the two are
    17	 * separate entries in the MHPCO clause book and move independently.
    18	 */
    19	function qualifiesForHighEnchantmentClause(item: Item): boolean {
    20	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
    21	}
