    23	/**
    24	 * The share of a damage the office carries before the deductible is charged.
    25	 *
    26	 * The MHPCO clause book grants full reimbursement as its standing position: an item
    27	 * the office insures is made whole unless a clause cuts that share. The dragon-material
    28	 * clause of the rules grants exactly that standing share, so it discriminates nothing
    29	 * and is not a branch here; the spec confirms this by settling a steel sword with no
    30	 * clause at all on the same full share. The high-enchantment clause is the one clause
    31	 * that cuts, and it takes precedence over full reimbursement wherever both would speak
    32	 * -- a dragon sword at enchantment 9 is settled at 50 %, not at 100 %.
    33	 */
    34	function reimbursedShareOf(item: Item): number {
    35	  return qualifiesForHighEnchantmentClause(item)
    36	    ? HIGH_ENCHANTMENT_REIMBURSED_SHARE
    37	    : FULL_REIMBURSEMENT;
    38	}
