    40	/**
    41	 * What the office owes for one damaged item: the share its clauses carry, less the
    42	 * deductible charged per damage event -- an incident that harms two items is
    43	 * reduced twice, so the payout is assembled per damaged item rather than per
    44	 * incident.
    45	 */
    46	function reimbursementFor(damage: Damage, damagedItem: Item): number {
    47	  return damage.amount * reimbursedShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
    48	}
